<?php
declare(strict_types=1);
function load_portfolio_env(string $file):void{if(!is_file($file))return;foreach(file($file,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||str_starts_with($line,'#')||!str_contains($line,'='))continue;[$key,$value]=array_map('trim',explode('=',$line,2));if(getenv($key)!==false)continue;putenv($key.'='.trim($value,"\"'"));}}
load_portfolio_env(dirname(__DIR__).'/.env');
if(is_file(__DIR__.'/.portfolio-secret.php'))require __DIR__.'/.portfolio-secret.php';
define('PORTFOLIO_DB_HOST',getenv('DB_HOST')?:'localhost');define('PORTFOLIO_DB_NAME',getenv('DB_NAME')?:'');define('PORTFOLIO_DB_USER',getenv('DB_USER')?:'');define('PORTFOLIO_DB_PASS',getenv('DB_PASS')?:'');if(!defined('PORTFOLIO_BRIDGE_SECRET'))define('PORTFOLIO_BRIDGE_SECRET',getenv('PORTFOLIO_BRIDGE_SECRET')?:'');
function portfolio_db():PDO{static $pdo;if($pdo instanceof PDO)return $pdo;$pdo=new PDO('mysql:host='.PORTFOLIO_DB_HOST.';dbname='.PORTFOLIO_DB_NAME.';charset=utf8mb4',PORTFOLIO_DB_USER,PORTFOLIO_DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$queries=["CREATE TABLE IF NOT EXISTS klyvex_portfolio_posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,excerpt VARCHAR(320) NOT NULL,content MEDIUMTEXT NOT NULL,status ENUM('draft','published') NOT NULL DEFAULT 'draft',published_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_klyvex_portfolio_public(status,published_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","CREATE TABLE IF NOT EXISTS klyvex_portfolio_comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,post_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL,comment TEXT NOT NULL,status ENUM('pending','approved') NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL,INDEX idx_klyvex_comments_post_status(post_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","CREATE TABLE IF NOT EXISTS klyvex_portfolio_likes (post_id BIGINT UNSIGNED NOT NULL,visitor_hash CHAR(64) NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(post_id,visitor_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","CREATE TABLE IF NOT EXISTS klyvex_portfolio_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value VARCHAR(255) NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","INSERT IGNORE INTO klyvex_portfolio_settings(setting_key,setting_value,updated_at) VALUES('comments_enabled','1',UTC_TIMESTAMP())"];foreach($queries as $query)$pdo->exec($query);return $pdo;}
